// Stand-in for the real data source (a SERP/AI-answer provider or an LLM API via an HTTP Request node).
// Each keyword is checked 3 times, because AI answers change between runs.
const answers = {
  '台北皮秒雷射推薦': ['推薦露米診所 https://www.lumi-clinic.example/pico 與晨光醫美', '可參考晨光醫美 https://aurora-aesthetics.example/x', '露米診所 https://lumi-clinic.example/pico'],
  '音波拉提效果':   ['見 https://wiki.example/hifu', 'https://lumi-clinic.example/hifu 有完整說明', '參考 https://health-news.example/hifu'],
  '皮秒雷射價格': ['', '費用約 6,000 到 12,000 元，見 https://health-news.example/price', '沒有引用來源'],
};
const out = [];
for (const [keyword, runs] of Object.entries(answers)) runs.forEach((answer, i) => out.push({ json: { keyword, run: i + 1, answer } }));
return out;

// Parse cited domains from each AI answer and flag whether the client's domain is cited.
// No URL class in the n8n sandbox, so hostnames are parsed with a regex.
const BRAND = 'lumi-clinic.example';   // the client's domain
const hostOf = u => ((u.match(/^https?:\/\/([^\/?#:]+)/i) || [])[1] || '').toLowerCase().replace(/^www\./, '');
return $input.all().map(({ json }) => {
  const answer = json.answer || '';
  const urls = answer.match(/https?:\/\/[^\s)\]」>，。]+/g) || [];
  const domains = [...new Set(urls.map(hostOf).filter(Boolean))];
  return { json: { keyword: json.keyword, run: json.run, cited_domains: domains, brand_cited: domains.includes(BRAND), empty_answer: !answer.trim() } };
});

// Visibility rate per keyword and overall, with a 95% Wilson interval (n is small, so the range matters).
const wilson = (k, n, z = 1.96) => {
  if (!n) return [0, 1];
  const p = k / n, d = 1 + z * z / n, c = (p + z * z / (2 * n)) / d;
  const h = (z * Math.sqrt(p * (1 - p) / n + z * z / (4 * n * n))) / d;
  return [Math.max(0, c - h), Math.min(1, c + h)];
};
const rows = $input.all().map(i => i.json).filter(r => !r.empty_answer);   // empty answers are not "not cited"
const byKw = {};
for (const r of rows) (byKw[r.keyword] ||= []).push(r.brand_cited);
const pct = x => Math.round(x * 100) + '%';
const perKeyword = Object.entries(byKw).map(([keyword, v]) => {
  const k = v.filter(Boolean).length, [lo, hi] = wilson(k, v.length);
  return { keyword, cited: `${k}/${v.length}`, rate: pct(k / v.length), ci95: `${pct(lo)}-${pct(hi)}` };
});
const k = rows.filter(r => r.brand_cited).length, [lo, hi] = wilson(k, rows.length);
return [{ json: { overall: `${k}/${rows.length} = ${pct(k / rows.length)} (95% CI ${pct(lo)}-${pct(hi)})`, dropped_empty_answers: $input.all().length - rows.length, perKeyword } }];

// Runs only on the IF node's "false" branch. Empty answers are a collection problem, not a lost citation,
// so they are reported separately.
const items = $input.all().map(i => i.json);
const misses = items.filter(r => !r.empty_answer).map(r => `${r.keyword} (run ${r.run})`);
const empty = items.filter(r => r.empty_answer).map(r => `${r.keyword} (run ${r.run})`);
return [{ json: {
  message: `Brand not cited in ${misses.length} answers: ${misses.join(', ')}`,
  check_collection: empty.length ? `Empty answers, check the data source: ${empty.join(', ')}` : null,
} }];
